fn add(a: i32, b: i32) -> i32 {
    a + b // no semicolon: this expression is the return value
}

fn main() {
    let x = 5;               // immutable
    let mut y = 10;          // mutable
    y += x;
    let x = add(x, x);       // shadowing: a new x, 10
    println!("{x} {y}");     // 10 15

    let n: u8 = "255".parse().unwrap();   // 255, only known at run time
    println!("{:?}", n.checked_add(1));   // None: would overflow
    println!("{}", n.wrapping_add(1));    // 0
    let m = n + 1;   // debug build: panic, attempt to add with overflow
    println!("{m}"); // release build: wraps and prints 0
}

#[derive(Debug)]
struct Point {
    x: i32,
    y: i32,
}

impl Point {
    fn new(x: i32, y: i32) -> Self {   // associated function
        Point { x, y }                  // no semicolon: the return value
    }
    fn manhattan(&self) -> i32 {        // method: called as p.manhattan()
        self.x.abs() + self.y.abs()
    }
}

fn main() {
    let p = Point::new(3, -4);
    println!("{:?} {}", p, p.manhattan()); // Point { x: 3, y: -4 } 7
    for i in 0..3 {
        print!("{i} ");                    // 0 1 2
    }
    println!();
}

enum Shape {
    Square(f64),                 // side length
    Rect { w: f64, h: f64 },
    Empty,
}

fn area(s: Shape) -> f64 {
    match s {
        Shape::Square(a) => a * a,
        Shape::Rect { w, h } => w * h,
        Shape::Empty => 0.0,
    }
}

fn main() {
    println!("{}", area(Shape::Rect { w: 2.0, h: 3.5 }));
    println!("{}", area(Shape::Square(3.0)));
    println!("{}", area(Shape::Empty));
}

// &[i32] is a borrowed view of some i32 values (lesson 6)
fn find(xs: &[i32], target: i32) -> Option<usize> {
    for i in 0..xs.len() {
        if xs[i] == target {
            return Some(i);
        }
    }
    None
}

fn main() {
    let xs = [7, 3, 9];
    match find(&xs, 9) {
        Some(i) => println!("found at {i}"), // found at 2
        None => println!("not found"),
    }
    println!("{:?}", find(&xs, 4));         // None
}

use std::num::ParseIntError;

fn parse_port(s: &str) -> Result<u16, ParseIntError> {
    let n: u16 = s.trim().parse()?;   // on Err: return it to the caller now
    Ok(n)
}

fn main() {
    println!("{:?}", parse_port("8080"));  // Ok(8080)
    println!("{:?}", parse_port("80x"));   // Err(ParseIntError { kind: InvalidDigit })
    println!("{:?}", parse_port("70000")); // Err(ParseIntError { kind: PosOverflow })
    match parse_port("443") {
        Ok(p) => println!("port {p}"),     // port 443
        Err(e) => println!("bad port: {e}"),
    }
}

