struct Parser<'a> {
    input: &'a str, // borrowed: a Parser cannot outlive this text
    pos: usize,     // byte offset of the next unread character
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    // The token borrows the text ('a), not the parser (&mut self).
    fn next_token(&mut self) -> Option<&'a str> {
        let rest = self.input[self.pos..].trim_start();
        if rest.is_empty() {
            return None;
        }
        let len = rest.find(' ').unwrap_or(rest.len());
        self.pos = self.input.len() - rest.len() + len;
        Some(&rest[..len])
    }
}

fn main() {
    let text = String::from("let x = 5");
    let first;
    {
        let mut p = Parser::new(&text);
        first = p.next_token().unwrap();
        println!("{:?}", p.next_token());
    } // p is dropped here
    println!("{first}"); // fine: first borrows text, not p
}

