use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Node {
    value: i32,
    parent: RefCell<Weak<Node>>,      // does not own the parent
    children: RefCell<Vec<Rc<Node>>>, // owns the children
}

fn counts(name: &str, n: &Rc<Node>) {
    println!("{name} strong = {}, weak = {}", Rc::strong_count(n), Rc::weak_count(n));
}

fn main() {
    let leaf = Rc::new(Node { value: 3, parent: RefCell::new(Weak::new()),
                              children: RefCell::new(vec![]) });
    counts("leaf", &leaf);                                  // 1, 0
    {
        let branch = Rc::new(Node { value: 5, parent: RefCell::new(Weak::new()),
                                    children: RefCell::new(vec![Rc::clone(&leaf)]) });
        *leaf.parent.borrow_mut() = Rc::downgrade(&branch);
        counts("branch", &branch);                          // 1, 1
        counts("leaf", &leaf);                              // 2, 0
        let p = leaf.parent.borrow().upgrade();
        println!("parent alive: {}", p.is_some());          // true
    } // branch dropped: its strong count reaches 0
    println!("parent alive: {}", leaf.parent.borrow().upgrade().is_some()); // false
    counts("leaf", &leaf);                                  // 1, 0
}

